CREATE TABLE IF NOT EXISTS scores_probidad (id TEXT PRIMARY KEY, politico_id TEXT NOT NULL UNIQUE, score_total REAL NOT NULL DEFAULT 50, score_asistencia REAL DEFAULT 50, score_gastos REAL DEFAULT 50, score_patrimonio REAL DEFAULT 50, score_banderas_rojas REAL DEFAULT 50, total_alertas_criticas INTEGER DEFAULT 0, total_alertas_altas INTEGER DEFAULT 0, total_incoherencias INTEGER DEFAULT 0, entidades_con_nepotismo INTEGER DEFAULT 0, porcentaje_asistencia REAL DEFAULT 0, fecha_calculo TEXT NOT NULL, version_algoritmo TEXT DEFAULT '1.0', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS historial_scores (id TEXT PRIMARY KEY, politico_id TEXT NOT NULL, score_total REAL NOT NULL, fecha TEXT NOT NULL, motivo TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS push_subscriptions (id TEXT PRIMARY KEY, politico_id TEXT NOT NULL, endpoint TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_scores_total ON scores_probidad(score_total);
CREATE INDEX IF NOT EXISTS idx_historial_scores ON historial_scores(politico_id, fecha);
